yaml_template:
services:
  easynode:
    image: {{ image }}
    container_name: {{ project_name }}
    ports:
{%- for port in ports %}
      - "{{ port.local_port }}:{{ port.container_port }}/{{ port.protocol }}"
{%- endfor %}
    volumes:
{%- for vol in volumes %}
      - {{ to_host_path(vol.host_path if (vol.host_path.startswith('/') or vol.shared) else project_name ~ '/' ~ vol.host_path) }}:{{ vol.container_path }}:{{ vol.mode }}
{%- endfor %}
    privileged: {{ privileged | lower }}
    restart: unless-stopped
    environment:
{%- for item in easynode_env %}
      - {{ item.key }}={{ item.value }}
{%- endfor %}
